def R(slug, name_vi, name_en, name_ru, lat, lon, cats, addr, rating, review,
      ps_vi, ps_en, ps_ru, pl_vi, pl_en, pl_ru, hi_vi, hi_en, hi_ru,
      practical, tags, sources=None, photo=None):
    return {
        "id": f"{REG}-{slug}",
        "slug": slug,
        "region": REG,
        "country": "vietnam",
        "region_name_vi": REGION_NAME,
        "federal_district": FD,
        "name_vi": name_vi,
        "name_ru": name_ru,
        "name_en": name_en,
        "categories": cats,
        "coordinates": {"lat": lat, "lon": lon},
        "address_vi": addr,
        "rating": rating,
        "review_summary_vi": review,
        "presentation_short_vi": ps_vi,
        "presentation_short_en": ps_en,
        "presentation_short_ru": ps_ru,
        "presentation_long_vi": pl_vi,
        "presentation_long_en": pl_en,
        "presentation_long_ru": pl_ru,
        "highlights_vi": hi_vi,
        "highlights_en": hi_en,
        "highlights_ru": hi_ru,
        "practical": practical,
        "photo": photo,
        "photo_credit": None,
        "official_site": None,
        "sources": sources or [],
        "tags": tags,
        "status": "enriched",
        "last_updated": TODAY,
    }


def rt(v, c):
    return {"value": v, "count": c, "source": "Google", "as_of": "2026-07"}


