def main():
    import shutil
    os.makedirs(os.path.dirname(F), exist_ok=True)
    d = json.load(open(F, encoding="utf-8")) if os.path.exists(F) else []
    if os.path.exists(F):
        stamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        shutil.copy(F, F + f".bak_add_{stamp}")
    have = {p["slug"] for p in d}
    added = [p for p in NEW if p["slug"] not in have]
    skipped = [p["slug"] for p in NEW if p["slug"] in have]
    d += added
    json.dump(d, open(F, "w", encoding="utf-8"), ensure_ascii=False, indent=2)
    print("Thêm mới:", len(added), "| Bỏ qua (đã có):", skipped)
    print("Tổng địa điểm Cần Thơ hiện có:", len(d))


if __name__ == "__main__":
    main()



